# Inventors Ladder: Flight (course key invflight). Helpers come from scripts/inventors/build.py.
# Lift equation as the Wrights used it: L = k S V^2 C_L (pounds, square feet, miles per hour); Smeaton's k = 0.005 in the
# old tables, about 0.0033 by the Wrights' measurements (NASA Glenn, Wright brothers pages).

LESSONS = {
 "wright-gliders": LES([
  P("Wilbur Wright (1867–1912) and Orville Wright (1871–1948) grew up in Dayton, Ohio, in a family of seven children; their father was a bishop. Neither finished high school with a diploma. They ran a printing business, then from 1892 a bicycle shop, where they built and repaired bikes. In 1878 their father had brought home a toy helicopter driven by a twisted rubber band. They never forgot it."),
  K("The Wrights saw that a flying machine needs three things: <b>wings for lift</b>, an <b>engine and propellers for push</b>, and <b>control</b> to balance and steer. Others focused on engines; the Wrights solved <b>control</b> first, with wing-warping, and then found that the <b>published data on wings was wrong</b>, so they measured it themselves in a wind tunnel."),
  H("The problem"),
  P("By the 1890s gliders had flown. In Germany, Otto Lilienthal made about 2,000 glides on wings he hung from, steering by swinging his body. In 1896 he lost control in a gust, crashed, and died. The Wrights read about his death and began studying flight seriously. In 1899 Wilbur wrote to the Smithsonian Institution asking for reading:"),
  Q("I am an enthusiast, but not a crank in the sense that I have some pet theories as to the proper construction of a flying machine. I wish to avail myself of all that is already known and then if possible add my mite to help on the future worker who will attain final success.",
    "Wilbur Wright", "Letter to the Smithsonian Institution, May 30, 1899", "Smithsonian Institution Archives; quoted by the Wright Brothers Aeroplane Company", "https://www.wright-brothers.org/History_Wing/Wright_Story/Inventing_the_Airplane/Inkling_of_Idea/More_Info.htm"),
  H("How the idea came: twisting a box"),
  P("Watching birds, Wilbur saw that they balance by twisting the tips of their wings, so one side gets more lift than the other. How could a machine do that? In the shop, he idly twisted a long, thin cardboard box that had held a bicycle inner tube. The top and bottom twisted in opposite directions at each end, yet the box stayed strong. Two wings joined like that, a biplane, could be twisted with cords. They called it <b>wing-warping</b>. In 1899 they tested it on a five-foot kite. It worked."),
  H("What they tried, and what failed"),
  P("They picked Kitty Hawk, on the Outer Banks of North Carolina, after asking the Weather Bureau where winds were strong and steady; the soft sand made landings safer. Their 1900 glider flew mostly as a kite. Their 1901 glider, bigger and built using the best published tables, gave only about a third of the lift the tables promised, and it was hard to control. They went home discouraged."),
  H("The wind tunnel, 1901"),
  P("Instead of giving up, they tested the tables. In their shop they built a wooden box about 6 feet long with a fan driven by the shop's engine, and inside it a balance made from bicycle spokes and hacksaw blades. They tested about 200 small wing shapes at different angles, measuring lift and drag. They found that a number everyone had used for over a century, Smeaton's coefficient, was too large: about 0.0033 rather than 0.005. They also learned which wing shapes and proportions worked best: long, narrow wings with a gentle curve."),
  K("The Wrights used the lift equation $L = k\\,S\\,V^2\\,C_L$: lift $L$ in pounds, wing area $S$ in square feet, air speed $V$ in miles per hour, $C_L$ the lift coefficient for the wing shape and angle (from their tunnel), and $k$ the Smeaton coefficient. Lift grows with the <b>square of the speed</b>."),
  V("iv-wing", None, "Change the angle of attack and the air speed. Compare the lift the old tables promised (Smeaton's 0.005) with the Wrights' measured value (0.0033). Past about 15 to 20 degrees the wing stalls."),
  EX("Using their numbers", "A wing has area 300 square feet and $C_L = 0.5$. At 20 mph, what lift does the Wrights' equation give with $k = 0.0033$?",
     ["$L = 0.0033 \\times 300 \\times 20^2 \\times 0.5$.", "$20^2 = 400$; $0.0033 \\times 300 = 0.99$; $0.99 \\times 400 = 396$; $396 \\times 0.5 = 198$."], "About 198 pounds."),
  EX("What the old number promised", "With Smeaton's old $k = 0.005$, the same wing would seem to give how much lift?",
     ["$0.005 \\times 300 \\times 400 \\times 0.5 = 300$ pounds.", "That is about 1.5 times the true value: a big enough error to wreck a design."], "300 pounds, which they never got."),
  H("The 1902 glider: control in three directions"),
  P("Their 1902 glider used the tunnel data, and it lifted as predicted. But in some turns it slid sideways and spun. They added a tail rudder, then made it movable and linked it to the wing-warping. Now they could control the machine in all three directions: nose up and down (pitch, with a front elevator), wings tipping (roll, by warping), and nose left and right (yaw, with the rudder). They made somewhere between 700 and 1,000 glides that fall. That three-axis control is still how airplanes are flown."),
  TL([
   ("1867", "Wilbur born near Millville, Indiana"),
   ("1871", "Orville born in Dayton, Ohio"),
   ("1878", "Their father gives them a toy helicopter"),
   ("1892", "They open the Wright Cycle Company"),
   ("1896", "Otto Lilienthal dies in a glider crash"),
   ("1899", "Wilbur writes to the Smithsonian; the wing-warping kite"),
   ("1900", "First glider at Kitty Hawk"),
   ("1901", "Disappointing glider; Wilbur's talk to the Western Society of Engineers; the wind tunnel"),
   ("1902", "Glider with movable rudder: three-axis control"),
  ]),
  EX("Lift and speed", "If air speed doubles and nothing else changes, what happens to lift?",
     ["Lift goes with $V^2$.", "$2^2 = 4$."], "It becomes 4 times larger."),
  H("What it led to"),
  P("With control solved and reliable wing data, only power was missing. That is the next topic."),
  M("Thinking the Wrights succeeded because they had a better engine. Their engine was modest. Their edge was control, careful measurement, and the habit of testing what everyone else took for granted."),
  TRYIT([("electromagnet", "Testing beats guessing: measure how turns and current change an electromagnet's strength")]),
  P("Read more: " + GK("Wright_brothers", "Wright brothers") + "."),
  TRY,
 ], "loc_wright", "wbm", "nasa_wright", "g_wright"),

 "wright-flyer": LES([
  P("By 1903 the Wrights had wings that lifted as predicted and controls that worked. Now they needed an engine light enough to carry and propellers to turn its power into push. Nobody sold either."),
  K("The Wrights built their own <b>engine</b> with their mechanic Charlie Taylor, and designed <b>propellers</b> by treating each blade as a small <b>rotating wing</b>. On <b>December 17, 1903</b>, the Flyer made four flights; the first lasted 12 seconds and covered 120 feet."),
  H("The engine"),
  P("Car makers could not supply a light enough engine, so Charlie Taylor, their shop mechanic, built one in about six weeks: four cylinders, an aluminum block, about 12 horsepower. Chains like bicycle chains drove two propellers that turned in opposite directions, so their twisting forces canceled."),
  H("The propeller: a wing that spins"),
  P("Ship propellers were made by trial and error. The Wrights realized a propeller blade is a wing moving in a spiral, so each part of the blade meets the air at its own speed and angle. Using their tunnel data, they worked out blade shapes that gave far more push than earlier designs. Their notes show months of argument between the brothers before it came together."),
  H("December 1903"),
  P("On December 14 Wilbur won a coin toss and tried first, but pulled up too steeply; the Flyer stalled and settled into the sand after about three seconds, with minor damage. On December 17, in a cold wind of over 20 miles per hour, it was Orville's turn. The Flyer ran along a wooden rail and rose. They took turns, four flights in all. That evening they sent a telegram home to their father, beginning:"),
  Q("Success four flights thursday morning all against twenty one mile wind started from Level with engine power alone average speed through air thirty one miles longest 57 seconds inform Press home Christmas.",
    "Orville Wright", "Telegram to Bishop Milton Wright, December 17, 1903", "Wilbur and Orville Wright Papers, Library of Congress", "https://www.loc.gov/collections/wilbur-and-orville-wright-papers/", "The telegraph office made errors: the longest flight was 59 seconds."),
  TB(["Flight", "Pilot", "Time", "Distance over the ground"], [
   ("1", "Orville", "12 seconds", "120 feet"),
   ("2", "Wilbur", "about 12 seconds", "about 175 feet"),
   ("3", "Orville", "15 seconds", "about 200 feet"),
   ("4", "Wilbur", "59 seconds", "852 feet"),
  ], "The four flights of December 17, 1903. After the fourth, a gust flipped the parked Flyer and damaged it; it never flew again."),
  EX("Ground speed", "The fourth flight went 852 feet in 59 seconds. What was its average speed over the ground, in feet per second?",
     ["$852 \\div 59 \\approx 14.4$ ft/s."], "About 14.4 feet per second, roughly 10 mph over the ground; into a strong headwind, its air speed was much higher."),
  W("A headwind helps a takeoff. The wing cares about the speed of the air over it. Flying into a 20 mph wind, the Flyer needed only a slow ground speed to get the air speed it needed for lift."),
  H("After 1903: learning to really fly"),
  P("The 1903 flights were short and straight. In 1904 and 1905, at Huffman Prairie, a cow pasture near Dayton, they learned to turn, circle and land safely. On October 5, 1905, Wilbur flew about 24 miles in 39 minutes. Few people believed it until 1908, when Wilbur flew in public in France and Orville in Virginia for the U.S. Army. During the Army trials a crash injured Orville and killed his passenger, Lieutenant Thomas Selfridge, the first person to die in an airplane accident. In 1909 the Army bought its first Wright airplane."),
  LEGEND("<p>Others claimed earlier powered flights, such as Gustave Whitehead in Connecticut in 1901. Historians generally find the evidence for those claims too thin. Samuel Langley's government-funded Aerodrome crashed into the Potomac twice in late 1903, just days before the Wrights' success. The Wrights' claim rests on witnesses, a famous photograph, their detailed notebooks, and above all on what they did next: controlled flights that anyone could see by 1908.</p>"),
  TL([
   ("Early 1903", "Charlie Taylor builds the engine; the brothers design the propellers"),
   ("December 8, 1903", "Langley's Aerodrome fails a second time"),
   ("December 14, 1903", "Wilbur's first attempt stalls after about three seconds"),
   ("December 17, 1903", "Four flights at Kill Devil Hills, near Kitty Hawk"),
   ("1904–1905", "Learning to circle at Huffman Prairie, Dayton"),
   ("1905", "A 39-minute flight"),
   ("1908", "Public flights in France and at Fort Myer, Virginia"),
   ("1909", "The U.S. Army buys a Wright airplane"),
   ("1912", "Wilbur dies of typhoid fever"),
   ("1948", "Orville dies; the 1903 Flyer goes to the Smithsonian"),
  ]),
  EX("From 12 seconds to 39 minutes", "How many times longer was the 39-minute flight of 1905 than the first 12-second flight?",
     ["39 minutes is $39 \\times 60 = 2340$ seconds.", "$2340 \\div 12 = 195$."], "195 times longer."),
  H("What it led to"),
  P("Within ten years airplanes crossed seas; within fifty, jets carried passengers across oceans. Every airplane still uses the Wrights' three-axis control, and engineers still test wings in wind tunnels."),
  M("Thinking the first flight was long or high. It was 12 seconds and about ten feet up. What mattered was that it was powered, controlled, and landed at a point as high as where it started."),
  TRYIT([("hand-generator", "Spin a coil to make electricity, the way a propeller spins in the air")]),
  P("Read more: " + GK("Wright_brothers", "Wright brothers") + " and " + GK("Wright_Flyer", "Wright Flyer") + "."),
  TRY,
 ], "loc_wright", "wbm", "nasa_wright", "g_wright"),
}
